INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(871303, 99252, 7263, '<td valign="top">A nice shoot here overall.<br/> <br/>I think the idea and lighting is great - her hand position equally as good. The things that let this image down is the face position and softness. To me she looks very uncomfortable bending her neck like that - it''s putting a strain which shows in her face. If she was in perfect profile I feel this would be much stringer composition wise.<br/> <br/>Apart from that, i do like it, and I like the edge burning bringing your eyes into the middle.<br/></td>', 'A nice shoot here overall. I think the idea and lighting is great - her hand position equally as good. The things that let this image down is the face position and softness. To me she looks very uncomfortable bending her neck like that - it''s putting a strain which shows in her face. If she was in perfect profile I feel this would be much stringer composition wise. Apart from that, i do like it, and I like the edge burning bringing your eyes into the middle.', '2004-08-23 05:30:00.000000', NULL, 1),
(871304, 99255, 7263, '<td valign="top">For a naked challenge - this really does not show me naked of any kind. For me the hardest part is meeting the criteria and this fails.<br/> <br/>That aside, i like your b&amp;w tones.</td>', 'For a naked challenge - this really does not show me naked of any kind. For me the hardest part is meeting the criteria and this fails. That aside, i like your b&w tones.', '2004-08-23 05:31:10.000000', NULL, 1),
