(871703, 98207, 19978, '<td valign="top">Yes, she is. Great response to the challenge, and very nice photo. I like the grain, it gives the whole photo a soft feel and correlates with her modesty. Very visually striking entry!</td>', 'Yes, she is. Great response to the challenge, and very nice photo. I like the grain, it gives the whole photo a soft feel and correlates with her modesty. Very visually striking entry!', '2004-08-23 11:37:55.000000', NULL, 1),
(871704, 98255, 25143, '<td valign="top">ghastly title - such an old cliche - and the stocking is not even alluring either</td>', 'ghastly title - such an old cliche - and the stocking is not even alluring either', '2004-08-23 11:38:10.000000', NULL, 1),
(871705, 99421, 2764, '<td valign="top">Why does she lookk so angry?</td>', 'Why does she lookk so angry?', '2004-08-23 11:38:33.000000', NULL, 1),
(871706, 99226, 8522, '<td valign="top">Wonderful shot, well posed. The light playing down the left side of the body and face is what makes this shot really great. Shame about the distracting corner in the background. It took me ages to notice the scar, so maybe it would have been better not drawing people''s attention to it in your title!</td>', 'Wonderful shot, well posed. The light playing down the left side of the body and face is what makes this shot really great. Shame about the distracting corner in the background. It took me ages to notice the scar, so maybe it would have been better not drawing people''s attention to it in your title!', '2004-08-23 11:38:33.000000', NULL, 1),
(871708, 98721, 25143, '<td valign="top">cool bird shape - too bad the shadow of the head is off-center: I would have liked total symmetry more; still, a very nice picture</td>', 'cool bird shape - too bad the shadow of the head is off-center: I would have liked total symmetry more; still, a very nice picture', '2004-08-23 11:39:19.000000', NULL, 1),
(871709, 99257, 19978, '<td valign="top">Indeed! Great composition, great response to the challenge! The scene seems a little overexposed though. Love it anyway.</td>', 'Indeed! Great composition, great response to the challenge! The scene seems a little overexposed though. Love it anyway.', '2004-08-23 11:39:22.000000', NULL, 1),
