(871761, 99020, 19978, '<td valign="top">A wonderful, lovely shot. Outstanding entry.</td>', 'A wonderful, lovely shot. Outstanding entry.', '2004-08-23 12:06:51.000000', NULL, 1),
(871762, 99191, 5286, '<td valign="top">Nice form. But very crumpled background is a little distracting...</td>', 'Nice form. But very crumpled background is a little distracting...', '2004-08-23 12:06:57.000000', NULL, 1),
