(871799, 99385, 19608, '<td valign="top">Emotional - the red lighting gives it a feeling of despair.  Just a bit too busy for me.</td>', 'Emotional - the red lighting gives it a feeling of despair.  Just a bit too busy for me.', '2004-08-23 12:17:02.000000', NULL, 1),
(871800, 99076, 19608, '<td valign="top">Funny!  Good expression and nice idea.</td>', 'Funny!  Good expression and nice idea.', '2004-08-23 12:17:58.000000', NULL, 1),
(871801, 99287, 8522, '<td valign="top">An interesting shot, I presume your PP has made your model look like a statue. I like the faint leaf outlines on the upper torso. Shame about the bad halo running around your model. Imaginative shot.</td>', 'An interesting shot, I presume your PP has made your model look like a statue. I like the faint leaf outlines on the upper torso. Shame about the bad halo running around your model. Imaginative shot.', '2004-08-23 12:18:31.000000', NULL, 1),
(871804, 98550, 19978, '<td valign="top">Simply beautiful. The soft tones and soft focus work extremely well. Your model is beautiful and her pose is sensuous. Great entry!!</td>', 'Simply beautiful. The soft tones and soft focus work extremely well. Your model is beautiful and her pose is sensuous. Great entry!!', '2004-08-23 12:20:47.000000', NULL, 1),
(871805, 99339, 21217, '<td valign="top">Nice portrait. Perfect use of B&amp;W</td>', 'Nice portrait. Perfect use of B&W', '2004-08-23 12:22:06.000000', NULL, 1),
