(878648, 99190, 772, '<td valign="top">Setzler Comment:<br/> <br/>Some general ratings (1-10):  These are some elements that I look for in great photographs, in no specific order<br/> <br/>Visual Appeal: 10<br/>Subject Appeal: 10<br/>Compositional Appeal: 8<br/>Effective use of color/bw: 10<br/>Creativity: 10<br/>Theme/Storytelling qualities: n/a<br/>Title: 8<br/> <br/>Additional Comments:<br/> <br/>Excellent abstract :)  Great shot.<br/></td>', 'Setzler Comment: Some general ratings (1-10):  These are some elements that I look for in great photographs, in no specific order Visual Appeal: 10Subject Appeal: 10Compositional Appeal: 8Effective use of color/bw: 10Creativity: 10Theme/Storytelling qualities: n/aTitle: 8 Additional Comments: Excellent abstract :)  Great shot.', '2004-08-26 13:57:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(878657, 99421, 20018, '<td valign="top">the pose/expression doesnt reflect the title to me; looks a bit soft as well</td>', 'the pose/expression doesnt reflect the title to me; looks a bit soft as well', '2004-08-26 14:01:45.000000', NULL, 1),
(878658, 99407, 20018, '<td valign="top">great background effect, but I''m not a fan of the pose</td>', 'great background effect, but I''m not a fan of the pose', '2004-08-26 14:03:13.000000', NULL, 1),
(878666, 98291, 20018, '<td valign="top">great shot but the reflection off the plastic is distracting and takes away from an otherwise potentially fantastic shot</td>', 'great shot but the reflection off the plastic is distracting and takes away from an otherwise potentially fantastic shot', '2004-08-26 14:06:09.000000', NULL, 1),
(878668, 98648, 20018, '<td valign="top">cute but background doesnt work for me</td>', 'cute but background doesnt work for me', '2004-08-26 14:07:35.000000', NULL, 1),
(878673, 98648, 772, '<td valign="top">Setzler Comment:<br/> <br/>Some general ratings (1-10):  These are some elements that I look for in great photographs, in no specific order<br/> <br/>Visual Appeal: 4<br/>Subject Appeal: 4<br/>Compositional Appeal: 5<br/>Effective use of color/bw: 5<br/>Creativity: 3<br/>Theme/Storytelling qualities: 7<br/>Title: 6<br/> <br/>Additional Comments:<br/> <br/>This is one of those photos that most people outside your friends/family will find difficult to embrace.  <br/></td>', 'Setzler Comment: Some general ratings (1-10):  These are some elements that I look for in great photographs, in no specific order Visual Appeal: 4Subject Appeal: 4Compositional Appeal: 5Effective use of color/bw: 5Creativity: 3Theme/Storytelling qualities: 7Title: 6 Additional Comments: This is one of those photos that most people outside your friends/family will find difficult to embrace.  ', '2004-08-26 14:11:04.000000', NULL, 1),
