(880093, 99228, 11467, '<td valign="top">Great use of light.<br/>Great pose.<br/>Focus is spot on.</td>', 'Great use of light.Great pose.Focus is spot on.', '2004-08-27 12:03:15.000000', NULL, 1),
(880095, 99226, 11467, '<td valign="top">Nice use of light and nice pose.<br/>The background needs more attention. Try a bedsheet or curtain to hide the corner in the wall.</td>', 'Nice use of light and nice pose.The background needs more attention. Try a bedsheet or curtain to hide the corner in the wall.', '2004-08-27 12:04:27.000000', NULL, 1),
